<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {api} from '../api';import {useData,useUI} from '../store';import {date,online} from '../domain';import type {Machine} from '../types';
interface MergePreview {source:{machine_id:number;client_id:string;label:string;hostname:string|null};target:{machine_id:number;client_id:string;label:string;hostname:string|null};report_count:number;snapshot_rows:number;hostname_differs:boolean;merge_token:string;expires_at:number}
const props=defineProps<{source:Machine|null}>(),emit=defineEmits<{close:[];merged:[]}>(),ui=useUI(),data=useData();
const targetId=ref<number|null>(null),preview=ref<MergePreview|null>(null),confirmation=ref(''),busy=ref(false),error=ref(''),done=ref('');
const targets=computed(()=>[...(data.snapshot?.machines||[])].filter(m=>m.machine_id!==props.source?.machine_id).sort((a,b)=>Number(b.hostname===props.source?.hostname)-Number(a.hostname===props.source?.hostname)||Number(online(b,data.now))-Number(online(a,data.now))));
watch(()=>props.source,()=>{targetId.value=null;preview.value=null;confirmation.value='';error.value='';done.value='';});watch(targetId,()=>{preview.value=null;confirmation.value='';error.value='';});watch(()=>ui.authorized,value=>{if(!value){preview.value=null;confirmation.value='';}});
/** 功能：管理员只读预览旧设备合并范围；参数：无；返回值：双方身份摘要与报告数量。 */
async function inspect(){if(!props.source||targetId.value===null||busy.value)return;if(!ui.authorized){ui.authOpen=true;return;}busy.value=true;error.value='';preview.value=null;confirmation.value='';try{preview.value=await api.mutate<MergePreview>(`/api/machine/${props.source.machine_id}/merge-preview`,{target_id:targetId.value});}catch(e){error.value=e instanceof Error?e.message:'预览失败';}finally{busy.value=false;}}
/** 功能：输入双方编号确认后执行一次合并，不自动重试；参数：无；返回值：实际迁移数，目标身份保留。 */
async function merge(){const p=preview.value;if(!p||busy.value||confirmation.value!==`${p.source.machine_id}->${p.target.machine_id}`)return;if(!ui.authorized){ui.authOpen=true;return;}busy.value=true;preview.value=null;error.value='';try{const r=await api.mutate<{moved_reports:number;moved_rows:number}>(`/api/machine/${p.source.machine_id}/merge`,{target_id:p.target.machine_id,merge_token:p.merge_token,confirmation:confirmation.value});done.value=`已迁移 ${r.moved_reports} 份报告、${r.moved_rows} 条窗口记录。目标设备身份和当前账号保持，旧设备接入已停用。`;await data.refresh();emit('merged');}catch(e){error.value=e instanceof Error?e.message:'结果未确认，请刷新核实后再操作';}finally{busy.value=false;}}
/** 功能：请求期间禁止关闭；参数：关闭回调；返回值：无。 */
function close(callback?:()=>void){if(busy.value)return;emit('close');callback?.();}
</script>
<template><el-dialog :model-value="Boolean(source)" title="合并旧设备" width="min(620px,95vw)" :before-close="close" :close-on-click-modal="false" :close-on-press-escape="!busy"><el-alert title="仅用于确认是同一电脑的旧记录。迁移历史后停用旧身份，旧采集器不能继续上报；目标ID、令牌、当前账号和周期保持不变。无法一键撤销。" type="warning" :closable="false"/><p>旧记录：<b>{{source?.label}}</b> · {{source?.hostname}} · #{{source?.machine_id}}</p><p class="mono">旧 client_id：{{source?.client_id}}</p><template v-if="!done"><el-select v-model="targetId" :disabled="busy" placeholder="选择要保留的目标设备" style="width:100%"><el-option v-for="m in targets" :key="m.machine_id" :value="m.machine_id" :label="`${m.label} · ${m.hostname||'主机名未知'} · #${m.machine_id} · ${m.client_id.slice(0,8)} · ${online(m,data.now)?'在线':'离线'}`"/></el-select><el-button :loading="busy" :disabled="targetId===null" style="margin:12px 0" @click="inspect">读取合并预览</el-button></template><template v-if="preview"><p>保留设备：<b>{{preview.target.label}}</b> · {{preview.target.hostname}} · #{{preview.target.machine_id}}</p><p class="mono">目标 client_id：{{preview.target.client_id}}</p><el-alert v-if="preview.hostname_differs" title="两条记录主机名不同，请确认确实来自同一电脑，切勿按名称猜测。" type="warning" :closable="false"/><p>迁移 {{preview.report_count}} 份报告、{{preview.snapshot_rows}} 条窗口记录；不将不同账号额度相加，不用旧报告覆盖目标当前账号。</p><p>预览有效至 {{date(preview.expires_at)}}。请输入 <code>{{preview.source.machine_id}}-&gt;{{preview.target.machine_id}}</code> 确认方向：</p><el-input v-model="confirmation" :disabled="busy" aria-label="输入源设备编号到目标设备编号确认合并"/></template><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="done" :title="done" type="success" :closable="false"/><template #footer><el-button :disabled="busy" @click="close()">{{done?'完成':'取消'}}</el-button><el-button v-if="!done" type="danger" :loading="busy" :disabled="!preview||!ui.authorized||confirmation!==`${preview.source.machine_id}->${preview.target.machine_id}`" @click="merge">确认合并并停用旧身份</el-button></template></el-dialog></template>
